import React, { useState, useEffect } from 'react';
import axios from 'axios';
//import { useNavigate } from 'react-router-dom';

function Summary() {
  const [initiatives, setInitiatives] = useState([]);
  const [isEditable, setIsEditable] = useState(false);
  //const navigate = useNavigate();
  const [loading, setLoading] = useState(true); // Loading state
  const [error, setError] = useState(null); // Error state
  
  
  // Fetch data from the backend
  useEffect(() => {
    axios
      .get('http://localhost:5000/api/initiatives')
      .then((res) => {
        setInitiatives(res.data);
        setLoading(false);
      })
      .catch((err) => {
        console.error('Error fetching initiatives:', err);
        setError('Failed to fetch data');
        setLoading(false);
      });
  }, []);

  
  
  // Handle input change in the grid
  // Handle input change in the grid
  const handleInputChange = (e, index, field) => {
    const updatedInitiatives = [...initiatives];
    updatedInitiatives[index][field] = e.target.value;
    setInitiatives(updatedInitiatives);
  };

  // Save updated data to the backend
  const handleSave = () => {
    axios
      .post('http://localhost:5000/api/updateInitiatives', { initiatives })
      .then(() => {
        alert('Data saved successfully!');
        setIsEditable(false);
      })
      .catch((err) => console.error('Error saving initiatives:', err));
  };

  if (loading) return <div>Loading...</div>;
  if (error) return <div>{error}</div>;
  
  
  return (
    <div style={{ padding: '2rem' }}>
      <h2>QE Initiatives Summary</h2>
      <table border="1" style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr>
            <th>Initiative Name</th>
            <th>Initiative Description</th>
            <th>Initiative Status</th>
            <th>Initiative Commentary</th>
          </tr>
        </thead>
        <tbody>
          {initiatives.map((initiative, index) => (
            <tr key={initiative.id || index}>
              <td>
                <input
                  type="text"
                  value={initiative.InitiativeName || ''}
                  disabled={!isEditable}
                  onChange={(e) => handleInputChange(e, index, 'InitiativeName')}
                />
              </td>
              <td>
                <input
                  type="text"
                  value={initiative.InitiativeDescription || ''}
                  disabled={!isEditable}
                  onChange={(e) =>
                    handleInputChange(e, index, 'InitiativeDescription')
                  }
                />
              </td>
              <td>
                <input
                  type="text"
                  value={initiative.InitiativeStatus || ''}
                  disabled={!isEditable}
                  onChange={(e) => handleInputChange(e, index, 'InitiativeStatus')}
                />
              </td>
              <td>
                <input
                  type="text"
                  value={initiative.InitiativeCommentary || ''}
                  disabled={!isEditable}
                  onChange={(e) =>
                    handleInputChange(e, index, 'InitiativeCommentary')
                  }
                />
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <button onClick={() => setIsEditable(true)} style={{ marginTop: '1rem' }}>
        Edit
      </button>
      <button
        onClick={handleSave}
        style={{ marginTop: '1rem', marginLeft: '1rem' }}
        disabled={!isEditable}
      >
        Save
      </button>
    </div>
  )
}

  export default Summary;
